from __future__ import annotations

from dataclasses import dataclass, field
from enum import Enum
from typing import Any


class CheckKind(Enum):
    """The kinds of checks performed on a package change."""

    CI_UPLOAD = "ci_upload"
    RELEASE_PIPELINE = "release_pipeline"
    REPO_PUBLIC = "repo_public"
    PR_LINK = "pr_link"


class CheckStatus(Enum):
    """Possible outcomes for a single check."""

    PASS = "pass"
    WARN = "warn"
    FAIL = "fail"
    NEEDS_AGENT = "needs_agent"


@dataclass
class CheckResult:
    """The result of a single check."""

    status: CheckStatus
    details: str


# Order used to aggregate several statuses into a single "worst" status.
# A FAIL is the most severe, followed by a check that needs agent attention,
# then a warning, and finally a pass.
_STATUS_SEVERITY = {
    CheckStatus.FAIL: 3,
    CheckStatus.NEEDS_AGENT: 2,
    CheckStatus.WARN: 1,
    CheckStatus.PASS: 0,
}


@dataclass
class PackageChange:
    """A single package version change detected in a diff."""

    name: str
    old_version: str | None
    new_version: str
    checks: dict[CheckKind, CheckResult] = field(default_factory=dict)
    repo_url: str | None = None

    @property
    def needs_agent(self) -> bool:
        """Return True if at least one check needs agent attention."""
        return any(
            result.status is CheckStatus.NEEDS_AGENT for result in self.checks.values()
        )

    def to_dict(self) -> dict[str, Any]:
        """Return a JSON-serializable representation."""
        return {
            "name": self.name,
            "old_version": self.old_version,
            "new_version": self.new_version,
            "repo_url": self.repo_url,
            "needs_agent": self.needs_agent,
            "checks": {
                kind.value: {
                    "status": result.status.value,
                    "details": result.details,
                }
                for kind, result in self.checks.items()
            },
        }


@dataclass
class CheckRunResult:
    """The result of running all checks for a PR."""

    pr_number: int
    packages: list[PackageChange] = field(default_factory=list)

    @property
    def needs_agent(self) -> bool:
        """Return True if any contained package needs agent attention."""
        return any(package.needs_agent for package in self.packages)

    def _aggregate_status(self, kind: CheckKind) -> str:
        """Return the worst status for a check kind across all packages."""
        statuses = [
            package.checks[kind].status
            for package in self.packages
            if kind in package.checks
        ]
        if not statuses:
            return "skipped"
        worst = max(statuses, key=lambda status: _STATUS_SEVERITY[status])
        return worst.value

    def to_dict(self) -> dict[str, Any]:
        """Return a JSON-serializable representation of the run."""
        # Imported lazily to avoid a circular import with the render module.
        from .render import render_comment

        checks_summary = {kind.value: self._aggregate_status(kind) for kind in CheckKind}

        result: dict[str, Any] = {
            "pr_number": self.pr_number,
            "needs_agent": self.needs_agent,
            "rendered_comment": render_comment(self),
            "checks": checks_summary,
            "packages": [package.to_dict() for package in self.packages],
        }

        # Expose each check kind at the top level as well, e.g. "repo_public".
        for kind in CheckKind:
            result[kind.value] = checks_summary[kind.value]

        return result
