import requests

_TIMEOUT = 30

# Hostnames that we accept as known, public code hosts. Matched exactly to
# avoid domain-suffix lookalikes such as "github.com.evil.com".
_KNOWN_CODE_HOSTS = frozenset(
    {"github.com", "gitlab.com", "www.github.com", "www.gitlab.com"}
)

# project_urls keys that, when present, are preferred over a value scan.
_PREFERRED_KEYS = ("Source", "Repository")


@dataclass
class PypiPackageInfo:
    """Information fetched from PyPI for a specific package version."""

    project_urls: dict[str, str]
    repo_url: str | None
    file_provenance_urls: list[str]
    found: bool


@dataclass
class ProvenanceResult:
    """The result of a provenance/attestation check."""

    has_attestation: bool
    publisher_kind: str | None
    recognized_publisher: bool
    detail: str


def _strip_control_chars(value: str) -> str:
    """Remove backtick and newline characters from a string."""
    return value.replace("`", "").replace("\r", "").replace("\n", "").strip()


def _is_known_code_host(url: str | None) -> bool:
    """Return True if the URL's hostname is exactly a known code host."""
    if not url:
        return False
    try:
        parsed = urlparse(url.strip())
    except ValueError:
        return False
    if parsed.scheme not in ("http", "https"):
        return False
    hostname = (parsed.hostname or "").lower()
    return hostname in _KNOWN_CODE_HOSTS


def _select_repo_url(project_urls: dict[str, str]) -> str | None:
    """Select a repository URL from the project URLs mapping.

    Prefers the ``Source`` / ``Repository`` keys when they point at a known
    code host, otherwise scans all values for a known-code-host URL.
    """
    for key in _PREFERRED_KEYS:
        value = project_urls.get(key)
        if _is_known_code_host(value):
            return _strip_control_chars(value)

    for value in project_urls.values():
        if _is_known_code_host(value):
            return _strip_control_chars(value)

    return None


def _build_provenance_urls(name: str, version: str, urls: list[dict]) -> list[str]:
    """Build the integrity provenance URL from the first listed file."""
    if not urls:
        return []
    filename = urls[0].get("filename")
    if not filename:
        return []
    return [f"https://pypi.org/integrity/{name}/{version}/{filename}/provenance"]


def _fetch_json(url: str) -> tuple[Any | None, int | None]:
    """Fetch JSON from a URL.

    Returns a ``(data, status_code)`` tuple. ``data`` is ``None`` when the
    request failed, the status was not 200, or the body was not valid JSON.
    ``status_code`` is ``None`` on a network-level error.
    """
    try:
        response = requests.get(url, timeout=_TIMEOUT)
    except requests.RequestException:
        return None, None

    status = response.status_code
    if status != 200:
        return None, status
    try:
        return response.json(), status
    except ValueError:
        return None, status


def _error_info() -> PypiPackageInfo:
    """Return the info object used for unreachable/invalid responses."""
    return PypiPackageInfo(
        project_urls={},
        repo_url=None,
        file_provenance_urls=[],
        found=False,
    )


