    for url in pkg.file_provenance_urls:
        data, status = _fetch_json(url)
        if status == 404:
            continue
        if data is None:
            # Non-404 failure for this file; try the next one.
            continue

        bundles = data.get("attestation_bundles") or []
        for bundle in bundles:
            publisher = bundle.get("publisher") or {}
            kind = publisher.get("kind")
            if not kind:
                # Entries without a publisher kind are skipped.
                continue
            publisher_kind = _strip_control_chars(str(kind))
            recognized = publisher_kind == "GitHub"
            if recognized:
                detail = (
                    f"PEP 740 provenance attestation present from recognized "
                    f"publisher '{publisher_kind}'."
                )
            else:
                detail = (
                    f"PEP 740 provenance attestation present but publisher "
                    f"'{publisher_kind}' is not recognised."
                )
            return ProvenanceResult(
                has_attestation=True,
                publisher_kind=publisher_kind,
                recognized_publisher=recognized,
                detail=detail,
            )

        if bundles:
            # Bundle(s) present but none carried a usable publisher kind.
            saw_bundle_without_kind = True

    if saw_bundle_without_kind:
        return ProvenanceResult(
            has_attestation=False,
            publisher_kind=None,
            recognized_publisher=False,
            detail="Provenance attestation bundle present but publisher kind could not be parsed.",
        )

    return ProvenanceResult(
        has_attestation=False,
        publisher_kind=None,
        recognized_publisher=False,
        detail="No PEP 740 provenance attestation present",
    )
