from __future__ import annotations

from .diff import parse_diff
from .models import (
    CheckKind,
    CheckResult,
    CheckRunResult,
    CheckStatus,
    PackageChange,
)
from .pypi import ProvenanceResult, PypiPackageInfo, check_provenance, fetch_package_info


def _build_checks(
    info: PypiPackageInfo, provenance: ProvenanceResult
) -> dict[CheckKind, CheckResult]:
    """Determine the check results for a single package."""
    if not info.found:
        detail = "Package version was not found on PyPI."
        return {
            CheckKind.CI_UPLOAD: CheckResult(CheckStatus.FAIL, detail),
            CheckKind.RELEASE_PIPELINE: CheckResult(CheckStatus.FAIL, detail),
            CheckKind.REPO_PUBLIC: CheckResult(CheckStatus.FAIL, detail),
            CheckKind.PR_LINK: CheckResult(CheckStatus.FAIL, detail),
        }

    checks: dict[CheckKind, CheckResult] = {}

    # CI upload / release pipeline are driven by the provenance attestation.
    if provenance.has_attestation and provenance.recognized_publisher:
        checks[CheckKind.CI_UPLOAD] = CheckResult(
            CheckStatus.PASS,
            "Uploaded with a PEP 740 attestation from a recognized publisher.",
        )
        checks[CheckKind.RELEASE_PIPELINE] = CheckResult(
            CheckStatus.PASS,
            f"Release published by recognized publisher "
            f"'{provenance.publisher_kind}'.",
        )
    elif provenance.has_attestation and not provenance.recognized_publisher:
        checks[CheckKind.CI_UPLOAD] = CheckResult(
            CheckStatus.WARN,
            "Attestation present but from an unrecognised publisher.",
        )
        checks[CheckKind.RELEASE_PIPELINE] = CheckResult(
            CheckStatus.NEEDS_AGENT,
            f"Release publisher unrecognised "
            f"('{provenance.publisher_kind}'); manual review required.",
        )
    else:
        checks[CheckKind.CI_UPLOAD] = CheckResult(
            CheckStatus.WARN,
            "No PEP 740 provenance attestation available for this upload.",
        )
        checks[CheckKind.RELEASE_PIPELINE] = CheckResult(
            CheckStatus.NEEDS_AGENT,
            "No attestation to confirm the release pipeline; manual review required.",
        )

    # Repository-based checks depend on an advertised repository URL.
    if info.repo_url is None:
        checks[CheckKind.REPO_PUBLIC] = CheckResult(
            CheckStatus.FAIL,
            "Package does not advertise a source repository URL.",
        )
        checks[CheckKind.PR_LINK] = CheckResult(
            CheckStatus.FAIL,
            "No repository available to locate the corresponding pull request.",
        )
    else:
        checks[CheckKind.REPO_PUBLIC] = CheckResult(
            CheckStatus.NEEDS_AGENT,
            f"Confirm the repository {info.repo_url} is public and legitimate.",
        )
        checks[CheckKind.PR_LINK] = CheckResult(
            CheckStatus.NEEDS_AGENT,
            "Confirm the change is backed by a pull request in the repository.",
        )

    return checks


def run_checks(pr_number: int, diff_text: str) -> CheckRunResult:
    """Parse a diff, fetch PyPI info, and run all checks per package."""
    changes = parse_diff(diff_text)

    checked: list[PackageChange] = []
    for change in changes:
        info = fetch_package_info(change.name, change.new_version)
        provenance = check_provenance(info)
        change.checks = _build_checks(info, provenance)
        change.repo_url = info.repo_url
        checked.append(change)

    return CheckRunResult(pr_number=pr_number, packages=checked)
