from __future__ import annotations

from .models import CheckKind, CheckResult, CheckRunResult, CheckStatus, PackageChange

MARKER = "<!-- requirements-check -->"

# Display order and human labels for the check kinds.
_CHECK_ORDER = (
    CheckKind.CI_UPLOAD,
    CheckKind.RELEASE_PIPELINE,
    CheckKind.REPO_PUBLIC,
    CheckKind.PR_LINK,
)

_STATUS_LABEL = {
    CheckStatus.PASS: "✅ pass",
    CheckStatus.WARN: "⚠️ warn",
    CheckStatus.FAIL: "❌ fail",
}

_MISSING = "—"


def _all_checks_pass(result: CheckRunResult) -> bool:
    """Return True if every present check in every package passes."""
    for package in result.packages:
        if not package.checks:
            return False
        for check in package.checks.values():
            if check.status is not CheckStatus.PASS:
                return False
    return True


def _version_label(package: PackageChange) -> str:
    """Return a human-readable version transition label."""
    if package.old_version is None:
        return f"new → {package.new_version}"
    return f"{package.old_version} → {package.new_version}"


def _cell(package: PackageChange, kind: CheckKind) -> str:
    """Render a single table cell for a package/check kind."""
    check = package.checks.get(kind)
    if check is None:
        return _MISSING
    if check.status is CheckStatus.NEEDS_AGENT:
        return f"{{{{CHECK_CELL:{package.name}:{kind.value}}}}}"
    return _STATUS_LABEL[check.status]


def _detail_bullet(package: PackageChange, kind: CheckKind) -> str:
    """Render a single detail bullet for a package/check kind."""
    check = package.checks.get(kind)
    if check is None:
        return f"  - `{kind.value}`: {_MISSING} skipped."
    if check.status is CheckStatus.NEEDS_AGENT:
        return f"  - `{kind.value}`: {{{{CHECK_DETAIL:{package.name}:{kind.value}}}}}"
    return f"  - `{kind.value}`: {check.details}"


def render_comment(result: CheckRunResult) -> str:
    """Render a Markdown comment string from a check run result."""
    lines: list[str] = [MARKER, ""]

    if not result.packages:
        lines.append("No tracked requirement changes detected.")
        return "\n".join(lines)

    all_pass = _all_checks_pass(result)
    needs_agent = result.needs_agent

    if all_pass:
        lines.append("All requirements checks passed. ✅")
    elif needs_agent:
        lines.append("Some requirements checks need agent review. 🔎")
    else:
        lines.append("Some requirements checks reported warnings or failures. ⚠️")

    lines.append("")

    # Summary table.
    header = "| Package | " + " | ".join(kind.value for kind in _CHECK_ORDER) + " |"
    separator = "| --- | " + " | ".join("---" for _ in _CHECK_ORDER) + " |"
    lines.append(header)
    lines.append(separator)
    for package in result.packages:
        cells = [f"`{package.name}` ({_version_label(package)})"]
        cells.extend(_cell(package, kind) for kind in _CHECK_ORDER)
        lines.append("| " + " | ".join(cells) + " |")

    lines.append("")

    # Details section. Expanded when agent attention is required.
    details_open = "<details open>" if needs_agent else "<details>"
    lines.append(details_open)
    lines.append("<summary>Check details</summary>")
    lines.append("")
    for package in result.packages:
